parseKgDetailed:
function parseKgDetailed(rawHtml) {
  const html =
    decodeMarketHtml(rawHtml);

  const rows = html.match(
    /<tr\b[^>]*>[\s\S]*?<\/tr>/gi,
  ) || [];

  const result = [];
  const seen = new Set();

  for (const row of rows) {
    if (!row.includes('data-odd=')) {
      continue;
    }

    const cells = [
      ...row.matchAll(
        /<td\b([^>]*)>/gi,
      ),
    ]
      .map(m => m[1])
      .filter(
        attrs =>
          attr(attrs, 'data-odd') != null,
      );

    if (cells.length < 2) {
      continue;
    }

    const bookmakerName =
      attr(row, 'data-bookie') ||
      attr(cells[0], 'data-bookie');

    if (!bookmakerName) {
      continue;
    }

    const bookmakerId =
      attr(cells[0], 'data-bid') ||
      attr(
        cells[0],
        'data-bookmaker-id',
      ) ||
      '';

    const byPosition = new Map();

    for (const cell of cells) {
      const pos = String(
        attr(cell, 'data-pos') || '',
      ).toLowerCase();

      const odd = numberOdd(
        attr(cell, 'data-odd'),
      );

      if (odd != null) {
        byPosition.set(pos, odd);
      }
    }

    const yesOdd =
      byPosition.get('y') ??
      numberOdd(
        attr(cells[0], 'data-odd'),
      );

    const noOdd =
      byPosition.get('n') ??
      numberOdd(
        attr(cells[1], 'data-odd'),
      );

    if (
      !(yesOdd > 1) ||
      !(noOdd > 1)
    ) {
      continue;
    }

    const key =
      bookmakerKey(bookmakerName);

    if (seen.has(key)) {
      continue;
    }

    seen.add(key);

    result.push({
      bookmakerId:
        String(bookmakerId || ''),
      bookmakerKey:
        bookmakerKey(bookmakerName),
      bookmakerName:
        String(bookmakerName).trim(),
      yesOdd,
      noOdd,
      yesClosed: false,
      noClosed: false,
      market: 'BTTS',
    });
  }

  result.sort(
    (a, b) =>
      a.bookmakerName.localeCompare(
        b.bookmakerName,
      ),
  );

  return result;
}

parseOpeningAt:
function parseOpeningAt(rawDate, cellCreated) {
  const opening = String(rawDate || '').match(
    /(\d{1,2})\.(\d{1,2})\.\s+(\d{1,2}):(\d{2})/
  );
  const current = String(cellCreated || '').match(
    /(\d{1,2}),(\d{1,2}),(\d{4}),(\d{1,2}),(\d{2})/
  );
  if (!opening || !current) return null;

  const day = Number(opening[1]);
  const month = Number(opening[2]);
  const hour = Number(opening[3]);
  const minute = Number(opening[4]);
  const currentDay = Number(current[1]);
  const currentMonth = Number(current[2]);
  let year = Number(current[3]);
  const currentHour = Number(current[4]);
  const currentMinute = Number(current[5]);

  const currentMs = Date.UTC(
    year, currentMonth - 1, currentDay, currentHour, currentMinute
  );
  let openingMs = Date.UTC(year, month - 1, day, hour, minute);

  if (openingMs > currentMs + 45 * 86400000) {
    year -= 1;
    openingMs = Date.UTC(year, month - 1, day, hour, minute);
  }
  return new Date(openingMs);
}

parseOverUnderDetailed:
function parseOverUnderDetailed(html) {
  const rows = [];
  const seen = new Set();

  const tableRows = [
    ...String(html).matchAll(
      /<tr\b[^>]*>([\s\S]*?)<\/tr>/gi
    )
  ].map(match => match[1]);

  for (const rowHtml of tableRows) {
    const oddTags = [
      ...rowHtml.matchAll(
        /<td\b[^>]*\bdata-odd\s*=\s*["'][^"']+["'][^>]*>/gi
      )
    ].map(match => match[0]);

    if (oddTags.length < 2) continue;

    const totalLine = extractTotalLine(rowHtml, oddTags);

    if (totalLine !== 1.5 && totalLine !== 2.5) {
      continue;
    }

    // BetExplorer O/U tablosunda kolon sırası:
    // Over -> Under
    const cells = oddTags.slice(0, 2).map(tag => ({
      value: Number(
        String(cellAttr(tag, 'data-odd') || '').replace(',', '.')
      ),
      oid: cellAttr(tag, 'data-oid'),
      bid: cellAttr(tag, 'data-bid'),
      bt: cellAttr(tag, 'data-bt'),
      sc: cellAttr(tag, 'data-sc'),
      hcp: cellAttr(tag, 'data-hcp'),
      created: cellAttr(tag, 'data-created'),
      closed: /\bclass\s*=\s*["'][^"']*\binactive\b[^"']*["']/i.test(tag)
    }));

    if (
      cells.some(
        cell =>
          !Number.isFinite(cell.value) ||
          cell.value <= 1 ||
          cell.value >= 1000
      )
    ) {
      continue;
    }

    const bookmakerName = extractBookmaker(rowHtml);
    const key = bookmakerKey(bookmakerName);

    if (!key) continue;

    const uniqueKey = key + '|' + totalLine.toFixed(1);
    if (seen.has(uniqueKey)) continue;

    rows.push({
      bookmakerId: key,
      bookmakerName,
      totalLine,

      overOdd: cells[0].value,
      underOdd: cells[1].value,

      overClosed: cells[0].closed === true,
      underClosed: cells[1].closed === true,

      cells
    });

    seen.add(uniqueKey);
  }

  return rows;
}
